from pathlib import Path
from collections import defaultdict
import json,hashlib,re
B=Path(__file__).resolve().parents[1];R=B/'revisao-r40';base=B.parent/'livro-diagramado-r39'
def read(p):return json.loads(p.read_text())
def save(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
m=read(B/'FONTES-E-VALIDACAO.json');old=read(base/'FONTES-E-VALIDACAO.json');draft=read(R/'PROVA-VISUAL-ANTES-AJUSTE-INDICE.json')
check=read(R/'CONFERENCIA.json');general=read(B/'evidencias/CONFERENCIA.json')
assert not check['problemas'] and not general['problemas']
assert check['sha256_pdf']==general['sha256_pdf']==m['sha256_pdf']
for c in range(1,21):assert [e for e in m['eventos'] if e.get('capitulo')==c]==[e for e in draft['eventos'] if e.get('capitulo')==c]
# Registrar inclusive diferenças de paginação, além das mudanças de composição.
a=defaultdict(list);z=defaultdict(list)
for e in old['eventos']:a[e.get('bloco') or '__navegacao_e_elementos_gerados__'].append(e)
for e in m['eventos']:z[e.get('bloco') or '__navegacao_e_elementos_gerados__'].append(e)
records=[]
for k in sorted(a.keys()|z.keys()):
 if a[k]!=z[k]:records.append({'id':f'R40-D{len(records)+1:03d}','bloco':k,'antes':a[k],'depois':z[k],'motivo':'Paginação, hierarquia semântica e sequência de leitura da R40; inclui deslocamentos decorrentes do sumário ampliado e da recomposição. Valores geométricos em pontos.'})
save(R/'ALTERACOES-DIAGRAMACAO.json',records)
save(R/'DECISOES-DE-COMPOSICAO.json',[
 {'id':'R40-C01','antes':'Sumário com 21 capítulos, em uma página.','depois':'Sumário de três páginas com 21 capítulos e 156 seções; os marcadores seguem sua hierarquia.','motivo':'Acesso aos procedimentos de criação, aptidões, Caminhos e Trilhas.'},
 {'id':'R40-C02','antes':'Habilidades com prefixos, sufixos, rótulos em negrito e subtítulos de diferentes hierarquias.','depois':'Nome da habilidade em entrada; nível em linha própria; detalhes, grupos e exemplos recebem os tratamentos aprovados correspondentes.','motivo':'Uniformizar a função dos títulos entre os seis Caminhos.'},
 {'id':'R40-C03','antes':'Introdução terminada em dois-pontos podia ser separada de toda a lista.','depois':'Introdução junto do primeiro item quando cabe na coluna.','motivo':'Preservar a continuidade da leitura.'},
 {'id':'R40-C04','antes':'Abertura de Trilha podia aparecer com apresentação/tabela, sem sua primeira habilidade.','depois':'Nas aberturas sem arte, reunir título, introdução, tabela curta e começo da primeira habilidade quando couberem.','motivo':'Evitar apresentação isolada; aberturas ilustradas existentes preservadas.'},
 {'id':'R40-C05','antes':{'indice_padding_superior_pt':2,'indice_padding_inferior_pt':2},'depois':{'indice_padding_superior_pt':1.8,'indice_padding_inferior_pt':1.8},'motivo':'Manter o índice em quatro páginas, sem uma quinta página com apenas duas entradas; fonte e tamanho mantidos.'}])
comp={'capitulos_diferentes':[],'capitulos_identicos_fora_paginacao':[],'paginas_externas_alteradas':[265,283,322]}
for c in range(1,22):
 def norm(events):
  es=[e for e in events if e.get('capitulo')==c];start=min(e['pagina'] for e in es)
  return [{k:(v-start if k=='pagina' else v) for k,v in e.items() if k!='faixa'} for e in es]
 comp['capitulos_identicos_fora_paginacao' if norm(old['eventos'])==norm(m['eventos']) else 'capitulos_diferentes'].append(c)
save(R/'COMPARACAO-COMPOSICAO.json',comp)
visual=[]
for p in list(range(2,5))+list(range(86,172))+[265,283,322]+list(range(369,373)):
 scope='Sumário' if p<5 else 'Caminhos e Trilhas' if p<172 else 'Índice' if p>=369 else 'Continuidade de lista'
 visual.append({'pagina':p,'escopo':scope,'metodo':'Inspeção visual de página renderizada; capítulo 6 também em painéis de seis páginas, com ampliação dos casos focais.','resultado':'Sem problema visual pendente identificado nesta rodada.'})
save(R/'REVISAO-VISUAL.json',{'sha256_pdf':m['sha256_pdf'],'paginas':visual,'reaproveitamento':'Após o ajuste exclusivo de espaçamento do índice, os eventos de desenho dos capítulos 1 a 20 ficaram exatamente iguais à prova inspecionada; o índice foi renderizado novamente.','composicoes_identicas_r39':comp['capitulos_identicos_fora_paginacao'],'limite':'Validação editorial e visual do escopo desta rodada; não substitui teste de mesa.'})
seq=read(R/'SEQUENCIAS-DE-NIVEL.json');inv=read(R/'INVENTARIO-CAMINHOS-E-TRILHAS.json')
lines=['# R40 — Sumário, hierarquia e ordem de níveis','',f'Entrega de 08/10/2026. {m["paginas"]} páginas. Base R39 preservada, com todos os arquivos comparados por SHA-256. Sem commit nem push.','','## O que mudou','','- Sumário ampliado de uma para três páginas: 21 capítulos e 156 seções, com links conferidos. Inclui Lapidação, Restrição Celestial e sua criação sem energia, Sem Técnica como Origem e como rota, os seis Caminhos, todas as Trilhas e as três rotas do Batedor.','- Marcadores do PDF seguem essa hierarquia. O índice distingue os destinos de Restrição Celestial e Sem Técnica.','- Habilidades dos seis Caminhos usam nome em título de entrada e nível em linha própria. Agrupadores, detalhes e exemplos conservam funções visuais distintas.','- Tabelas de progressão acrescentadas às três Trilhas do Guia, usando exclusivamente os nomes e níveis já existentes. Demais tabelas padronizadas; o Batedor mantém sua tabela conjunta de três rotas.','- Assassino: todas as habilidades de nível 2 precedem as duas de nível 11. Golpe Cirúrgico aparece na sequência inicial.','- Pugilista: Rajada Marcial passa a aparecer após as habilidades de nível 2; a primeira frase explica que é a melhoria de Corpo Treinado recebida no nível 7.','- Evocador: Dificultar a Resistência, nível 7, aparece após todas as intervenções iniciais de nível 2.','- Tratar e Retomar e outras capacidades antes apresentadas como marcadores receberam a hierarquia de habilidade.','- Aberturas de Trilhas sem arte e introduções de listas receberam proteção contra separação prematura. Leitura segue a coluna esquerda inteira e depois a direita.','- Espaçamento vertical das entradas do índice reduzido em 0,4 pt por linha, mantendo fonte e tamanho; isso evitou uma página adicional com apenas duas entradas.','','## Preservação do conteúdo','','São 91 blocos com antes/depois em `ALTERACOES-TEXTO.json`. A comparação com a R39 não encontrou diferenças textuais fora desses registros. As mudanças são de títulos, metadados, tabelas de consulta, ordenação e explicitação da Rajada; não houve alteração de custo, efeito ou nível de aquisição.','','As regras, exemplos e contas foram preservados. O exemplo de Escolher a Próxima Vítima foi deslocado junto da habilidade, sem reescrita; seu destaque foi relocalizado no catálogo. Nenhum exemplo foi recalculado. Os custos de Resposta Coordenada e a frequência de Todos no Mesmo Plano foram separados do parágrafo, sem retirada de conteúdo. Fontes, tamanhos, arte, capa e créditos mantidos.','','## Conferência individual de níveis','','A coluna abaixo mostra a sequência de aquisição; repetições de um mesmo nível foram resumidas. Batedor possui uma tabela conjunta e três rotas conferidas separadamente. Referências a evoluções futuras dentro de uma regra não foram confundidas com novas habilidades.','','| Caminho, Trilha ou rota | Início na R40 | Sequência |','|---|---:|---|']
for row in inv:
 name=row['nome'];s=seq.get(name,[]);levels=[]
 for x in s:
  if not levels or levels[-1]!=x['nivel']:levels.append(x['nivel'])
 detail=' → '.join(map(str,levels)) or 'Tabela conjunta; conferir as três rotas abaixo.'
 lines.append(f'| {name} | {row["pagina"]} | {detail} |')
lines+=['','Fluidez no nível 15 e Obras maiores foram conferidos como evoluções das capacidades existentes, na sequência correta. As escolhas internas de uma mesma capacidade permanecem juntas; os nomes de todas as entradas verificadas estão em `SEQUENCIAS-DE-NIVEL.json`.','','## Validação final','','- '+format(general['checagens'], ',').replace(',', '.')+' verificações automáticas; zero problemas detectados. Cobertura: conteúdo dos 500 blocos, extração do PDF, fontes, margens, sobreposições, destinos e numeração.',f'- {general["links_internos"]} links internos e {general["marcadores"]} marcadores conferidos; 177 linhas clicáveis do sumário verificadas individualmente.','- Nenhuma sequência descendente de níveis no inventário e nenhum par de títulos adjacentes com a mesma apresentação detectado.','- Inspeção visual das 86 páginas do capítulo Caminhos e Trilhas (86–171), das três páginas do sumário, das quatro do índice e das três páginas externas recompostas (265, 283 e 322).','- Os outros 16 capítulos preservam a composição da R39, descontada a mudança na numeração das páginas.','- As folgas antes de aberturas ilustradas foram preservadas; esta rodada prioriza a hierarquia e a continuidade, sem reduzir o tamanho da letra.','',f'O livro passou de 367 para {m["paginas"]} páginas: duas adicionais no sumário e quatro na recomposição de Caminhos e Trilhas. O índice permaneceu com quatro páginas.','','## Registros','','- `ALTERACOES-TEXTO.json`: antes/depois dos 91 blocos.','- `ALTERACOES-HIERARQUIA.json`: classificação dos títulos alterados.','- `ALTERACOES-DIAGRAMACAO.json`: todos os blocos com diferenças de posição, composição ou página, inclusive elementos gerados.','- `DECISOES-DE-COMPOSICAO.json`: decisões de navegação e continuidade.','- `CONFERENCIA.json`, `REVISAO-VISUAL.json` e `COMPARACAO-COMPOSICAO.json`: evidências da revisão.','','## Próxima etapa','','Leitura e aceite do autor sobre a R40. Para analisar retornos que envolvam entendimento e cruzamento de regras, recomendação editorial: GPT-6 Astra, esforço alto. A recomendação considera o tipo de trabalho, não uma comparação medida entre modelos.']
(R/'RELATORIO.md').write_text('\n'.join(lines)+'\n')
